#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <termios.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/select.h>

#define MAX_COLS 256
#define MAX_ROWS 256

/* Global variables */
int async_scroll = 0;
int bold_on = 0;
int bold_all = 0;
int screensaver = 0;
int linux_mode = 0;
int no_bold = 0;
int old_style = 0;
int shadow_only = 0;
int lock_mode = 0;
int force_linux = 0;
int x_mode = 0;
int rainbow_mode = 0;
int lambda_mode = 0;
int change_chars = 0;
int update_delay = 4;
char color = 'g';  /* g=green, r=red, b=blue, y=yellow, c=cyan, m=magenta, w=white, k=black */
char message[256] = "";
char tty[256] = "";

int cols, rows;
int fd_tty = -1;
struct termios original_tty, new_tty;
int running = 1;

/* Character set for matrix effect */
const char matrix_chars[] = "01";
const char extended_chars[] = "ｦｧｨｩｪｫｬｭｮｯｰｱｲｳｴｵｶｷｸｹｺｻｼｽｾﾀﾁﾂﾃﾄﾅﾆﾇﾈﾉﾊﾋﾌﾍﾎﾏﾐﾑﾒﾓﾔﾕﾗﾘﾜ";
const char lambda_char = 'λ';

typedef struct {
    int y;
    int length;
    int speed;
    int active;
} Column;

Column *columns;
int **matrix;

/* Color codes */
const char *color_codes[] = {
    "\033[32m",  /* green */
    "\033[31m",  /* red */
    "\033[34m",  /* blue */
    "\033[33m",  /* yellow */
    "\033[36m",  /* cyan */
    "\033[35m",  /* magenta */
    "\033[37m",  /* white */
    "\033[30m"   /* black */
};

const char *get_color_code(char c) {
    switch(c) {
        case 'r': return color_codes[1];
        case 'b': return color_codes[2];
        case 'y': return color_codes[3];
        case 'c': return color_codes[4];
        case 'm': return color_codes[5];
        case 'w': return color_codes[6];
        case 'k': return color_codes[7];
        default: return color_codes[0]; /* green */
    }
}

void print_usage() {
    printf(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n");
    printf(" -a: Asynchronous scroll\n");
    printf(" -b: Bold characters on\n");
    printf(" -B: All bold characters (overrides -b)\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
    printf(" -f: Force the linux $TERM type to be on\n");
    printf(" -l: Linux mode (uses matrix console font)\n");
    printf(" -L: Lock mode (can be closed from another terminal)\n");
    printf(" -o: Use old-style scrolling\n");
    printf(" -h: Print usage and exit\n");
    printf(" -n: No bold characters (overrides -b and -B, default)\n");
    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
    printf(" -V: Print version information and exit\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
    printf(" -C [color]: Use this color for matrix (default green)\n");
    printf(" -r: rainbow mode\n");
    printf(" -m: lambda mode\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
    printf(" -t [tty]: Set tty to use\n");
}

void print_version() {
    printf(" CMatrix version 2.0 (compiled 19:59:42, Apr 17 2026)\n");
    printf("Email: abishekvashok@gmail.com\n");
    printf("Web: https://github.com/abishekvashok/cmatrix\n");
}

void parse_args(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) {
        if (argv[i][0] != '-') continue;

        for (int j = 1; argv[i][j]; j++) {
            char opt = argv[i][j];
            switch(opt) {
                case 'a': async_scroll = 1; break;
                case 'b': bold_on = 1; break;
                case 'B': bold_all = 1; no_bold = 0; break;
                case 'c': lambda_mode = 0; /* Japanese mode - use extended chars */ break;
                case 'f': force_linux = 1; break;
                case 'l': linux_mode = 1; break;
                case 'L': lock_mode = 1; break;
                case 'o': old_style = 1; break;
                case 'h':
                case '?': print_usage(); exit(0);
                case 'n': no_bold = 1; bold_on = 0; bold_all = 0; break;
                case 's': screensaver = 1; break;
                case 'x': x_mode = 1; break;
                case 'V': print_version(); exit(0);
                case 'M':
                    if (i + 1 < argc) {
                        strncpy(message, argv[++i], sizeof(message) - 1);
                        message[sizeof(message) - 1] = '\0';
                    }
                    j = strlen(argv[i]);
                    break;
                case 'u':
                    if (i + 1 < argc) {
                        update_delay = atoi(argv[++i]);
                        if (update_delay < 0) update_delay = 0;
                        if (update_delay > 10) update_delay = 10;
                    }
                    j = strlen(argv[i]);
                    break;
                case 'C':
                    if (i + 1 < argc) {
                        char *col = argv[++i];
                        if (strlen(col) > 0) {
                            color = col[0];
                        }
                    }
                    j = strlen(argv[i]);
                    break;
                case 't':
                    if (i + 1 < argc) {
                        strncpy(tty, argv[++i], sizeof(tty) - 1);
                        tty[sizeof(tty) - 1] = '\0';
                    }
                    j = strlen(argv[i]);
                    break;
                case 'r': rainbow_mode = 1; break;
                case 'm': lambda_mode = 1; break;
                case 'k': change_chars = 1; break;
            }
        }
    }
}

void get_terminal_size() {
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == -1) {
        cols = 80;
        rows = 24;
    } else {
        cols = ws.ws_col;
        rows = ws.ws_row;
    }
}

void init_matrix() {
    columns = (Column *)malloc(sizeof(Column) * cols);
    matrix = (int **)malloc(sizeof(int *) * rows);
    for (int i = 0; i < rows; i++) {
        matrix[i] = (int *)malloc(sizeof(int) * cols);
        memset(matrix[i], 0, sizeof(int) * cols);
    }

    for (int i = 0; i < cols; i++) {
        columns[i].y = 0;
        columns[i].length = rand() % (rows / 2) + rows / 4;
        columns[i].speed = async_scroll ? (rand() % 3) + 1 : 1;
        columns[i].active = 1;
    }
}

void cleanup() {
    /* Clear screen and restore cursor */
    printf("\033[2J\033[H\033[?25h");
    if (fd_tty != -1) {
        tcsetattr(fd_tty, TCSAFLUSH, &original_tty);
        if (tty[0]) close(fd_tty);
    }

    /* Free memory */
    if (matrix) {
        for (int i = 0; i < rows; i++) {
            if (matrix[i]) free(matrix[i]);
        }
        free(matrix);
    }
    if (columns) free(columns);
}

void signal_handler(int sig) {
    running = 0;
}

void draw_matrix() {
    /* Save cursor and hide it */
    printf("\033[?1049h\033[?25l");
    fflush(stdout);

    for (int frame = 0; running; frame++) {
        printf("\033[H\033[2J");

        /* Update columns */
        for (int x = 0; x < cols; x++) {
            if (async_scroll || old_style) {
                columns[x].y += columns[x].speed;
                if (columns[x].y > rows) {
                    columns[x].y = 0;
                    columns[x].length = rand() % (rows / 2) + rows / 4;
                }
            } else {
                columns[x].y += 1;
                if (columns[x].y > rows) {
                    columns[x].y = 0;
                    columns[x].length = rand() % (rows / 2) + rows / 4;
                }
            }
        }

        /* Draw screen */
        for (int y = 0; y < rows; y++) {
            for (int x = 0; x < cols; x++) {
                int head = columns[x].y;
                int tail_start = head - columns[x].length;

                char ch = ' ';
                int is_head = 0;
                int is_body = 0;

                if (y == head) {
                    is_head = 1;
                    ch = matrix_chars[rand() % 2];
                } else if (y > tail_start && y < head) {
                    is_body = 1;
                    ch = matrix_chars[rand() % 2];
                }

                if (is_head || is_body) {
                    if (rainbow_mode) {
                        int color_idx = (frame + x + y) % 8;
                        printf("%s", color_codes[color_idx]);
                    } else {
                        printf("%s", get_color_code(color));
                    }

                    if (is_head) {
                        printf("\033[1m");
                    } else if (bold_all) {
                        printf("\033[1m");
                    } else if (bold_on && rand() % 2) {
                        printf("\033[1m");
                    }

                    if (shadow_only && is_body && y != head - 1) {
                        printf("%c\033[0m", ' ');
                    } else {
                        printf("%c\033[0m", ch);
                    }
                } else {
                    printf(" ");
                }
            }
            printf("\n");
        }

        /* Print message if set */
        if (message[0]) {
            printf("\033[%d;%dH\033[1m%s\033[0m", rows / 2, (cols - strlen(message)) / 2, message);
        }

        fflush(stdout);

        /* Calculate sleep time based on update_delay */
        usleep((11 - update_delay) * 10000);

        /* Check for input in screensaver mode */
        if (screensaver) {
            struct timeval tv;
            fd_set readfds;
            FD_ZERO(&readfds);
            FD_SET(STDIN_FILENO, &readfds);
            tv.tv_sec = 0;
            tv.tv_usec = 0;

            if (select(STDIN_FILENO + 1, &readfds, NULL, NULL, &tv) > 0) {
                running = 0;
            }
        }
    }

    /* Restore terminal */
    printf("\033[?1049l");
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    srand(time(NULL));

    parse_args(argc, argv);

    /* Setup terminal */
    get_terminal_size();

    if (tcgetattr(STDOUT_FILENO, &original_tty) == -1) {
        fprintf(stderr, "Error opening terminal: unknown.\n");
        return 1;
    }

    new_tty = original_tty;
    new_tty.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDOUT_FILENO, TCSANOW, &new_tty);

    atexit(cleanup);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_matrix();
    draw_matrix();

    return 0;
}
